{"cards": [{"node_code": "N_5751934c0c4fa809", "definition": "研究微尺度下物体抓取、精确位置控制及组件组装的技术，涵盖微夹持器、微定位平台及微装配工艺与设备。", "boundary": "聚焦于微尺度（微米至亚毫米级）的静态或准静态操作任务，强调对微小物体的物理接触、定位精度及装配过程。边界在于区分于动态运动控制，若涉及微型机器人的自主导航或长距离运动，归入“磁、电、光与声场驱动微机器人”；若涉及流体环境下的生物样本操作，归入“微流控、生物操作与群体微机器人”。", "includes": ["微夹持器设计与微力控制", "微定位平台及高精度位移技术", "微装配工艺、流程及自动化设备"], "excludes": ["宏观尺度的机械装配或工业机器人操作", "不涉及机械接触或定位的纯流体操控技术"], "sibling_distinctions": [{"other_code": "N_149660399ca0d521", "rule": "本节点关注对静止或受控物体的抓取与组装（操作对象），兄弟节点关注机器人本体的驱动与运动（操作主体）。"}, {"other_code": "N_8b634f9090a17951", "rule": "本节点关注固体微部件的机械装配，兄弟节点关注流体环境中的生物样本操控及多机器人协同。"}], "cross_boundary_rule": "若微装配过程依赖特定场驱动机器人执行，可次关联“磁、电、光与声场驱动微机器人”，但装配工艺与夹持技术主挂载本节点。"}, {"node_code": "N_149660399ca0d521", "definition": "研究利用磁场、电场、光场或声场等非接触方式驱动微型机器人运动、转向及执行任务的技术与系统。", "boundary": "聚焦于微型机器人本体的驱动机制、运动学分析及控制策略，强调外部场对微尺度物体的远程操控能力。边界在于区分于具体操作任务，若重点在于利用这些机器人进行特定装配或生物操作，可次关联相应操作节点，但驱动原理与机器人本体设计主挂载本节点；若涉及宏观机器人，归入“机器人基础与机械臂”。", "includes": ["磁驱动、电驱动、光驱动及声驱动微机器人设计", "微机器人运动学、动力学及轨迹控制", "多场耦合驱动机制及远程操控技术"], "excludes": ["不涉及外部场驱动的自供能微机器人（如化学燃料驱动）", "宏观尺度的电磁或声控设备"], "sibling_distinctions": [{"other_code": "N_5751934c0c4fa809", "rule": "本节点关注机器人如何被驱动和运动（主体），兄弟节点关注机器人或工具如何抓取和组装物体（客体）。"}, {"other_code": "N_8b634f9090a17951", "rule": "本节点关注单个或少数机器人的场驱动机制，兄弟节点关注流体环境下的生物操作及大规模群体协同行为。"}], "cross_boundary_rule": "若场驱动微机器人用于微装配，可次关联“微夹持、微定位与微装配”，但驱动与控制算法主挂载本节点。"}, {"node_code": "N_8b634f9090a17951", "definition": "研究微流控环境下的生物样本操控、细胞处理及多个微型机器人协同工作的群体智能与行为模式。", "boundary": "聚焦于流体介质中的微操作、生物医学应用及多机器人系统。边界在于强调“流体环境”、“生物对象”或“群体协同”，若涉及固体微部件的机械装配，归入“微夹持、微定位与微装配”；若仅关注单个机器人的场驱动原理，归入“磁、电、光与声场驱动微机器人”。", "includes": ["微流控芯片中的细胞捕获、分选及操作", "微机器人集群的协同控制、通信及任务分配", "基于微流控的生物医学诊断与治疗操作"], "excludes": ["不涉及流体或生物对象的纯机械微装配", "宏观尺度的流体力学或生物医学工程研究"], "sibling_distinctions": [{"other_code": "N_5751934c0c4fa809", "rule": "本节点关注流体中的生物操作及群体行为，兄弟节点关注固体微部件的机械装配。"}, {"other_code": "N_149660399ca0d521", "rule": "本节点关注多机器人协同及流体环境应用，兄弟节点关注单机器人场驱动机制。"}], "cross_boundary_rule": "若群体微机器人依赖特定场驱动，可次关联“磁、电、光与声场驱动微机器人”，但群体协同策略及生物操作主挂载本节点。"}]}
